 const stops=Object.entries(DATA.stops).filter(([key])=>key!=='depot').map(([key,stop])=>{const pt=transform(stop.point);if(!visible(pt))return '';const isTarget=key===r.target;return `<g data-demo-stop="${key}"><circle cx="${n(pt[0])}" cy="${n(pt[1])}" r="${isTarget?6:4}" fill="${p.route}" stroke="${p.marker}" stroke-width="2"/>${label([pt[0],pt[1]-20],stop.label+' · '+key+'동',driving?14:16,p.route)}</g>`;}).join('');
